enum COLOR = {red, green, ivory, yellow, blue};
enum NATIONALITY = {englishman, spaniard, ukrainian, norwegian, japanese};
enum DRINK = {coffee, tea, milk, orange_juice, water};
enum CIGAR = {old_gold, kools, chesterfields, lucky_strike, parliaments};
enum PET = {dog, snails, fox, horse, zebra};

int: N = 5;

array[1..N] of var COLOR: house_color;
array[1..N] of var NATIONALITY: house_nationality;
array[1..N] of var DRINK: house_drink;
array[1..N] of var CIGAR: house_cigar;
array[1..N] of var PET: house_pet;

% Clue 1: The Englishman lives in the red house.
constraint forall(i in 1..N)(house_nationality[i] = englishman -> house_color[i] = red);

% Clue 2: The Spaniard owns the dog.
constraint forall(i in 1..N)(house_nationality[i] = spaniard -> house_pet[i] = dog);

% Clue 3: Coffee is drunk in the green house.
constraint forall(i in 1..N)(house_color[i] = green -> house_drink[i] = coffee);

% Clue 4: The Ukrainian drinks tea.
constraint forall(i in 1..N)(house_nationality[i] = ukrainian -> house_drink[i] = tea);

% Clue 5: The green house is immediately to the right of the ivory house.
constraint forall(i in 1..N-1)(house_color[i] = ivory -> house_color[i+1] = green);

% Clue 6: The Old Gold smoker owns snails.
constraint forall(i in 1..N)(house_cigar[i] = old_gold -> house_pet[i] = snails);

% Clue 7: Kools are smoked in the yellow house.
constraint forall(i in 1..N)(house_cigar[i] = kools -> house_color[i] = yellow);

% Clue 8: Milk is drunk in the middle house.
constraint house_drink[3] = milk;

% Clue 9: The Norwegian lives in the first house.
constraint house_nationality[1] = norwegian;

% Clue 10: The man who smokes Chesterfields lives in the house next to the man with the fox.
constraint forall(i in 1..N-1)(house_cigar[i] = chesterfields -> house_pet[i+1] = fox \/ house_pet[i] = fox -> house_cigar[i+1] = chesterfields);

% Clue 11: Kools are smoked in the house next to the house where the horse is kept.
constraint forall(i in 1..N-1)(house_cigar[i] = kools -> house_pet[i+1] = horse \/ house_pet[i] = horse -> house_cigar[i+1] = kools);

% Clue 12: The Lucky Strike smoker drinks orange juice.
constraint forall(i in 1..N)(house_cigar[i] = lucky_strike -> house_drink[i] = orange_juice);

% Clue 13: The Japanese smokes Parliaments.
constraint forall(i in 1..N)(house_nationality[i] = japanese -> house_cigar[i] = parliaments);

% Clue 14: The Norwegian lives next to the blue house.
constraint house_color[2] = blue /\ house_nationality[1] = norwegian;

% All different constraints
constraint alldifferent(house_color);
constraint alldifferent(house_nationality);
constraint alldifferent(house_drink);
constraint alldifferent(house_cigar);
constraint alldifferent(house_pet);

