array[1..5] of var PET: pet;

constraint
    nationality[1] = Norwegian /\  % The Norwegian lives in the first house.
    drink[3] = milk /\  % Milk is drunk in the middle house (House 3).
    color[2] = blue /\  % The Norwegian lives next to the blue house.

    % The Englishman lives in the red house.
    exists(i in 1..5)(nationality[i] = Englishman -> color[i] = red) /\

    % The Spaniard owns the dog.
    exists(i in 1..5)(nationality[i] = Spaniard -> pet[i] = dog) /\

    % Coffee is drunk in the green house.
    exists(i in 1..5)(color[i] = green -> drink[i] = coffee) /\

    % The Ukrainian drinks tea.
    exists(i in 1..5)(nationality[i] = Ukrainian -> drink[i] = tea) /\

    % The green house is immediately to the right of the ivory house.
    forall(i in 1..4)(color[i] = ivory -> color[i+1] = green) /\

    % The Old Gold smoker owns snails.
    exists(i in 1..5)(cigar[i] = Old_Gold -> pet[i] = snails) /\

    % Kools are smoked in the yellow house.
    exists(i in 1..5)(color[i] = yellow -> cigar[i] = Kools) /\

    % The man who smokes Chesterfields lives in the house next to the man with the fox.
    forall(i in 1..4)(cigar[i] = Chesterfields <-> pet[i+1] = fox) /\
    forall(i in 2..5)(cigar[i] = Chesterfields <-> pet[i-1] = fox) /\

    % Kools are smoked in the house next to the house where the horse is kept.
    forall(i in 1..4)(cigar[i] = Kools <-> pet[i+1] = horse) /\
    forall(i in 2..5)(cigar[i] = Kools <-> pet[i-1] = horse) /\

    % The Lucky Strike smoker drinks orange juice.
    exists(i in 1..5)(cigar[i] = Lucky_Strike -> drink[i] = orange_juice) /\

    % The Japanese smokes Parliaments.
    exists(i in 1..5)(nationality[i] = Japanese -> cigar[i] = Parliaments);

