constraint exists(r in 1..4)(exists(w in (r+1)..5)(pens[r] = rabbit /\ pens[w] = wolf));

% Wolf preys on rabbit (this can be represented by the placements)
constraint forall(i in 1..5)(pens[i] <> rabbit \/ pens[i + 1] <> wolf);

solve satisfy;

include "globals.mzn";

enum ANIMAL = {tortoise, parrot, goat, rabbit, wolf};
array[1..5] of var ANIMAL: pen;

constraint pen[1] = tortoise;
constraint pen[2] = parrot;
constraint pen[3] = goat;

constraint forall(i in 1..5)(
    (pen[i] = rabbit) -> (exists(j in (i+1)..5)(pen[j] = wolf))
);

constraint forall(i in 1..5)(
    (pen[i] = wolf) -> (exists(j in 1..(i-1))(pen[j] = rabbit))
);

solve satisfy;
